```go
package paasio

import (
	"io"
	"sync"
)

// readCounter wraps an io.Reader and counts the bytes and operations read.
type readCounter struct {
	r    io.Reader
	mu   sync.Mutex
	n    int64
	nops int
}

// writeCounter wraps an io.Writer and counts the bytes and operations written.
type writeCounter struct {
	w    io.Writer
	mu   sync.Mutex
	n    int64
	nops int
}

// readWriteCounter combines a readCounter and a writeCounter.
type readWriteCounter struct {
	*readCounter
	*writeCounter
}

func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{w: writer}
}

func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{r: reader}
}

func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter:  &readCounter{r: readwriter},
		writeCounter: &writeCounter{w: readwriter},
	}
}

func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.r.Read(p)
	rc.mu.Lock()
	rc.n += int64(n)
	rc.nops++
	rc.mu.Unlock()
	return n, err
}

func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.n, rc.nops
}

func (wc *writeCounter) Write(p []byte) (int, error) {
	n, err := wc.w.Write(p)
	wc.mu.Lock()
	wc.n += int64(n)
	wc.nops++
	wc.mu.Unlock()
	return n, err
}

func (wc *writeCounter) WriteCount() (int64, int) {
	wc.mu.Lock()
	defer wc.mu.Unlock()
	return wc.n, wc.nops
}
```

One consideration: in testRead, `rc.ReadCount()` requires at least 2 operations — io.Copy makes multiple calls, so no problem.

